shell_commands:
/bin/zsh -lc "cat > src/orchestration/tools/enum-validation.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

it('rejects a value outside the declared enum specs/hal-engine-tool-input-validation/spec.md#3', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {unit: {enum: ['celsius']}}}},
    async () => 'accepted'
  );
  expect((await registry.execute('weather', {unit: 'fahrenheit'})).result).toMatch(/unit.*allowed values/i);
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/enum-validation.test.ts"

/bin/zsh -lc "cat > src/orchestration/tools/enum-validation.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

it('reports escaped paths for missing properties specs/hal-engine-tool-input-validation/spec.md#1', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {address: {type: 'object', required: ['postal/code']}}}},
    async () => 'accepted'
  );
  expect((await registry.execute('weather', {address: {}})).result).toMatch(/\\/address\\/postal~1code.*required/i);
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/enum-validation.test.ts"
